/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var zeros = require( '@stdlib/array/base/zeros' );
var copy = require( '@stdlib/array/base/copy' );
var gwhereRows = require( './../lib/main.js' );


// FIXTURES //

var rntantb = require( './fixtures/row_major_nta_ntb.json' );
var rtantb = require( './fixtures/row_major_ta_ntb.json' );
var rntatb = require( './fixtures/row_major_nta_tb.json' );
var rtatb = require( './fixtures/row_major_ta_tb.json' );
var cntantb = require( './fixtures/column_major_nta_ntb.json' );
var cntatb = require( './fixtures/column_major_nta_tb.json' );
var ctantb = require( './fixtures/column_major_ta_ntb.json' );
var ctatb = require( './fixtures/column_major_ta_tb.json' );
var rAllTrue = require( './fixtures/row_major_all_true.json' );
var rAllFalse = require( './fixtures/row_major_all_false.json' );
var rSingleRow = require( './fixtures/row_major_single_row.json' );
var rSingleCol = require( './fixtures/row_major_single_column.json' );
var rCondStride = require( './fixtures/row_major_condition_stride.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gwhereRows, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 13', function test( t ) {
	t.strictEqual( gwhereRows.length, 13, 'returns expected value' );
	t.end();
});

tape( 'the function returns a reference to the output array', function test( t ) {
	var data;
	var out;
	var ret;
	var a;
	var b;

	data = rntantb;

	a = copy( data.A );
	b = copy( data.B );
	out = zeros( data.out_expected.length );

	ret = gwhereRows( data.order, data.transA, data.transB, data.M, data.N, data.condition, data.strideC, a, data.lda, b, data.ldb, out, data.ldo );

	t.strictEqual( ret, out, 'returns expected value' );

	t.end();
});

tape( 'the function throws an error if provided an invalid first argument', function test( t ) {
	var values;
	var data;
	var i;

	data = rntantb;

	values = [
		'foo',
		'bar',
		'beep',
		'boop'
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			gwhereRows( value, data.transA, data.transB, data.M, data.N, data.condition, data.strideC, data.A, data.lda, data.B, data.ldb, data.A, data.lda );
		};
	}
});

